1	/**
2	 * Authority Admission & Resource Confinement Engine
3	 * Nexus Issue #12 — WP-02 (INC-03, AUTH-001..012, ACT-001..004, RES-001..004)
4	 */
5	
6	import * as path from "node:path";
7	import * as fs from "node:fs";
8	import {
9	  InvocationRequest,
10	  InvocationContext,
11	  AdmissionDecision,
12	  ResourceConfinementDecision,
13	  AuthorityAdmissionHook,
14	  ResourceConfinementHook,
15	  extractTargetResources,
16	} from "./spine.js";
17	import { defaultRegistry } from "./capabilities.js";
18	
19	export type AuthorityScope = "exact" | "subtree" | "workspace" | "full_access";
20	
21	export interface AuthorityGrant {
22	  id?: string;
23	  actor?: string | string[];
24	  executionDomain?: string | string[];
25	  capabilities: string[];
26	  scope: AuthorityScope;
27	  resources?: string[];
28	  readOnly?: boolean;
29	}
30	
31	export interface AuthorityConfig {
32	  fullAccess?: boolean;
33	  readOnly?: boolean;
34	  grants?: AuthorityGrant[];
35	  allowedDomains?: string[];
36	  safeReadOnlyCommandRegex?: RegExp;
37	}
38	
39	/**
40	 * Standard safe commands allowed under --read-only mode.
41	 */
42	export const DEFAULT_SAFE_READONLY_COMMAND_REGEX =
43	  /^\s*(ls|dir|pwd|echo|cat|head|tail|grep|rg|find|diff|wc|which|where|git\s+(status|log|diff|branch|show)|npm\s+list|node\s+-v|rustc\s+-v)(\s+.*)?$/i;
44	
45	/**
46	 * Validates whether a shell command is safe to execute under read-only mode.
47	 * Enforces AUTH-009 and AUTH-010:
48	 * 1. Rejects shell composition, pipelines, command substitutions, redirections, and separators.
49	 * 2. Validates base executable against safe command allowlist.
50	 * 3. Inspects executable arguments to prevent subcommands or options that perform mutation.
51	 */
52	export function isSafeReadOnlyCommand(
53	  command: string,
54	  customRegex?: RegExp
55	): boolean {
56	  if (!command || typeof command !== "string") return false;
57	  const trimmed = command.trim();
58	  if (trimmed.length === 0) return false;
59	
60	  // 1. Strict rejection of shell control, chaining, substitution, and redirection metacharacters:
61	  // ;      - command separator
62	  // &      - background operator or logical AND (&&)
63	  // |      - pipeline or logical OR (||)
64	  // >      - output redirection (truncate or append)
65	  // <      - input redirection or process substitution
66	  // $      - variable / command / arithmetic substitution ($(cmd), $VAR, $((expr)))
67	  // `      - backtick command substitution (`cmd`)
68	  // \n, \r - newline command separators
69	  // (, )   - subshell execution / grouping
70	  // {, }   - command block grouping
71	  // \      - escape character
72	  if (/[><&;|`$\n\r(){}\\]/.test(trimmed)) {
73	    return false;
74	  }
75	
76	  // 2. Validate against the safe read-only command allowlist
77	  const regex = customRegex || DEFAULT_SAFE_READONLY_COMMAND_REGEX;
78	  if (!regex.test(trimmed)) {
79	    return false;
80	  }
81	
82	  // 3. Inspect command-specific argument escapes for allowed executables:
83	
84	  // 3a. 'find' command: reject mutating or execution arguments (-delete, -exec, -ok, -fprint, etc.)
85	  if (/^\s*find\b/i.test(trimmed)) {
86	    if (/\s-(delete|exec|execdir|ok|okdir|fprint|fprint0|fprintf|fls)\b/i.test(trimmed)) {
87	      return false;
88	    }
89	  }
90	
91	  // 3b. 'git' command: reject output redirection flags (--output, -o)
92	  if (/^\s*git\b/i.test(trimmed)) {
93	    if (/\s(--output\b|-o\s)/i.test(trimmed) || /\s--output=/i.test(trimmed)) {
94	      return false;
95	    }
96	
97	    // 3c. 'git branch': only allow inspection/listing; reject creation, deletion, renaming
98	    if (/^\s*git\s+branch\b/i.test(trimmed)) {
99	      // Reject deletion (-d, -D, --delete), renaming (-m, -M, --move), copying (-c, -C, --copy), upstream setting (-u)
100	      if (/\s(-[dDmMceCu]|--delete|--move|--copy|--set-upstream|--edit-description)\b/i.test(trimmed)) {
101	        return false;
102	      }
103	      // Inspect remaining tokens after 'git branch': any non-flag token not preceded by -l or --list is branch creation/mutation
104	      const afterBranch = trimmed.replace(/^\s*git\s+branch\s*/i, "").trim();
105	      if (afterBranch.length > 0) {
106	        const tokens = afterBranch.split(/\s+/);
107	        let expectsPattern = false;
108	        for (const token of tokens) {
109	          if (token === "-l" || token === "--list") {
110	            expectsPattern = true;
111	          } else if (token.startsWith("-")) {
112	            // Safe flag, e.g. -a, -r, -v, -vv, --remotes, --all, --show-current
113	            expectsPattern = false;
114	          } else if (expectsPattern) {
115	            // Allowed pattern argument for --list (e.g. "feat/*")
116	            expectsPattern = false;
117	          } else {
118	            // Positional argument without --list means branch creation/mutation: reject
119	            return false;
120	          }
121	        }
122	      }
123	    }
124	  }
125	
126	  return true;
127	}
