129	/**
130	 * Authority Admission & Resource Confinement Engine
131	 */
132	export class AuthorityAdmissionEngine {
133	  private fullAccess: boolean = false;
134	  private readOnly: boolean = false;
135	  private grants: AuthorityGrant[] = [];
136	  private allowedDomains: Set<string> | null = null;
137	  private safeCommandRegex: RegExp = DEFAULT_SAFE_READONLY_COMMAND_REGEX;
138	
139	  constructor(config: AuthorityConfig = {}) {
140	    this.fullAccess = Boolean(config.fullAccess);
141	    this.readOnly = Boolean(config.readOnly);
142	    this.grants = config.grants ? [...config.grants] : [];
143	    if (config.allowedDomains && config.allowedDomains.length > 0) {
144	      this.allowedDomains = new Set(config.allowedDomains);
145	    }
146	    if (config.safeReadOnlyCommandRegex) {
147	      this.safeCommandRegex = config.safeReadOnlyCommandRegex;
148	    }
149	  }
150	
151	  public setFullAccess(enabled: boolean): void {
152	    this.fullAccess = enabled;
153	  }
154	
155	  public isFullAccess(): boolean {
156	    return this.fullAccess;
157	  }
158	
159	  public setReadOnly(enabled: boolean): void {
160	    this.readOnly = enabled;
161	  }
162	
163	  public isReadOnly(): boolean {
164	    return this.readOnly;
165	  }
166	
167	  public addGrant(grant: AuthorityGrant): void {
168	    this.grants.push(grant);
169	  }
170	
171	  public clearGrants(): void {
172	    this.grants = [];
173	  }
174	
175	  public getGrants(): AuthorityGrant[] {
176	    return [...this.grants];
177	  }
178	
179	  /**
180	   * Authority Admission Gate (Stage 3A)
181	   * Evaluates capability authority, domain isolation, and read-only enforcement.
182	   */
183	  public async admit(
184	    request: InvocationRequest,
185	    context: InvocationContext
186	  ): Promise<AdmissionDecision> {
187	    const actor = request.actor || "agent";
188	    const domain = request.executionDomain || "agent_orchestration";
189	    const toolName = request.toolName;
190	
191	    // Check domain allowlist if configured
192	    if (this.allowedDomains && !this.allowedDomains.has(domain) && !this.allowedDomains.has("*")) {
193	      return {
194	        admitted: false,
195	        reason: `AUTH-012: Execution domain '${domain}' is not permitted by domain policy.`,
196	      };
197	    }
198	
199	    // Resolve canonical capability
200	    const capability = defaultRegistry.getByToolName(toolName);
201	    if (!capability) {
202	      return {
203	        admitted: false,
204	        reason: `AUTH-003: Unrecognized tool name '${toolName}' cannot be mapped to canonical capability.`,
205	      };
206	    }
207	
208	    const effectiveReadOnly = this.readOnly || Boolean(context.readOnly);
209	
210	    // Read-only gating (AUTH-009, AUTH-010)
211	    if (effectiveReadOnly) {
212	      if (capability.id === "proc_exec" || capability.id === "command_execution" || toolName === "run_command") {
213	        const cmd = request.args?.command;
214	        if (!isSafeReadOnlyCommand(cmd, this.safeCommandRegex)) {
215	          return {
216	            admitted: false,
217	            reason: `AUTH-010: Read-only mode violation: Command '${cmd}' is not permitted in read-only mode. Only safe inspection commands are permitted.`,
218	          };
219	        }
220	      } else if (capability.mutating) {
221	        return {
222	          admitted: false,
223	          reason: `AUTH-009: Read-only mode violation: Capability '${capability.id}' mutates candidate state and is denied in read-only mode.`,
224	        };
225	      }
226	    }
227	
228	    // Full-access bypass of further grant checks (AUTH-007, AUTH-008)
229	    if (this.fullAccess) {
230	      return {
231	        admitted: true,
232	        effectiveScope: "full_access",
233	      };
234	    }
235	
236	    // If explicit grants are defined, evaluate matching grant (AUTH-001, AUTH-006)
237	    if (this.grants.length > 0) {
238	      const matchingGrant = this.findMatchingGrant(actor, domain, capability.id, toolName);
239	      if (!matchingGrant) {
240	        return {
241	          admitted: false,
242	          reason: `AUTH-006: Fail-closed: No authority grant authorizes capability '${capability.id}' for actor '${actor}' in domain '${domain}'.`,
243	        };
244	      }
245	
246	      return {
247	        admitted: true,
248	        effectiveScope: matchingGrant.scope,
249	      };
250	    }
251	
252	    // Default workspace authority grant if no explicit grants defined
253	    return {
254	      admitted: true,
255	      effectiveScope: "workspace",
256	    };
257	  }
258	
259	  /**
260	   * Resource Confinement Gate (Stage 3B)
261	   * Enforces workspace boundary containment, cwd confinement, and exact/subtree scopes.
262	   */
263	  public async confine(
264	    request: InvocationRequest,
265	    context: InvocationContext
266	  ): Promise<ResourceConfinementDecision> {
267	    const wsRoot = path.resolve(context.workspaceRoot || process.cwd());
268	    const actor = request.actor || "agent";
269	    const domain = request.executionDomain || "agent_orchestration";
270	    const capability = defaultRegistry.getByToolName(request.toolName);
271	    const capId = capability ? capability.id : request.toolName;
272	
273	    // In full-access mode, resource confinement is broad (AUTH-007, AUTH-008)
274	    if (this.fullAccess) {
275	      return { confined: true };
276	    }
277	
278	    // Determine effective scope from matching grant
279	    let effectiveScope: AuthorityScope = "workspace";
280	    let allowedResources: string[] | undefined = undefined;
281	
282	    if (this.grants.length > 0) {
283	      const grant = this.findMatchingGrant(actor, domain, capId, request.toolName);
284	      if (grant) {
285	        effectiveScope = grant.scope;
286	        allowedResources = grant.resources;
287	        if (effectiveScope === "full_access") {
288	          return { confined: true };
289	        }
290	      }
291	    }
292	
293	    // 1. Verify subprocess cwd confinement (RES-002, AUTH-011)
294	    if ((capId === "proc_exec" || capId === "command_execution" || request.toolName === "run_command") && request.args?.cwd) {
295	      const cwdStr = String(request.args.cwd).trim();
296	      const targetCwd = path.isAbsolute(cwdStr) ? path.normalize(cwdStr) : path.resolve(wsRoot, cwdStr);
297	      const rel = path.relative(wsRoot, targetCwd);
298	      if (rel.startsWith("..") || path.isAbsolute(rel)) {
299	        return {
300	          confined: false,
301	          reason: `RES-002: Security Violation: Working directory '${cwdStr}' escapes workspace jail.`,
302	        };
303	      }
304	    }
305	
306	    // 2. Extract and verify all target resource paths (RES-001, RES-004, AUTH-004, AUTH-005)
307	    const targets = extractTargetResources(request.toolName, request.args);
308	    for (const target of targets) {
309	      const cleanPath = target.trim();
310	      if (!cleanPath) continue;
311	
312	      const absTarget = path.isAbsolute(cleanPath)
313	        ? path.normalize(cleanPath)
314	        : path.resolve(wsRoot, cleanPath);
315	
316	      // Verify path stays within workspaceRoot (RES-004)
317	      const relToWs = path.relative(wsRoot, absTarget);
318	      if (relToWs.startsWith("..") || path.isAbsolute(relToWs)) {
319	        return {
320	          confined: false,
321	          reason: `RES-004: Security Violation: Path '${cleanPath}' escapes workspace jail.`,
322	        };
323	      }
324	
325	      // Check scope-specific constraints (AUTH-004, AUTH-005)
326	      if (effectiveScope === "exact") {
327	        if (!allowedResources || allowedResources.length === 0) {
328	          return {
329	            confined: false,
330	            reason: `AUTH-004: Exact scope grant requires specific resources list.`,
331	          };
332	        }
333	        const matchesExact = allowedResources.some((r) => {
334	          const absAllowed = path.isAbsolute(r) ? path.normalize(r) : path.resolve(wsRoot, r);
335	          return absAllowed === absTarget;
336	        });
337	        if (!matchesExact) {
338	          return {
339	            confined: false,
340	            reason: `AUTH-005: Security Violation: Path '${cleanPath}' does not match any exact authorized resource (no sibling inheritance).`,
341	          };
342	        }
343	      } else if (effectiveScope === "subtree") {
344	        if (!allowedResources || allowedResources.length === 0) {
345	          return {
346	            confined: false,
347	            reason: `AUTH-004: Subtree scope grant requires specific resources list.`,
348	          };
349	        }
350	        const matchesSubtree = allowedResources.some((r) => {
351	          const absAllowed = path.isAbsolute(r) ? path.normalize(r) : path.resolve(wsRoot, r);
352	          const rel = path.relative(absAllowed, absTarget);
353	          return !rel.startsWith("..") && !path.isAbsolute(rel);
354	        });
355	        if (!matchesSubtree) {
356	          return {
357	            confined: false,
358	            reason: `AUTH-005: Security Violation: Path '${cleanPath}' is outside authorized subtree scope (no sibling inheritance).`,
359	          };
360	        }
361	      }
362	    }
363	
364	    return { confined: true };
365	  }
366	
367	  /**
368	   * Creates an AuthorityAdmissionHook for ExecutionSpine.
369	   */
370	  public createAdmissionHook(): AuthorityAdmissionHook {
371	    return (request, context) => this.admit(request, context);
372	  }
373	
374	  /**
375	   * Creates a ResourceConfinementHook for ExecutionSpine.
376	   */
377	  public createConfinementHook(): ResourceConfinementHook {
378	    return (request, context) => this.confine(request, context);
379	  }
380	
381	  private findMatchingGrant(
382	    actor: string,
383	    domain: string,
384	    capabilityId: string,
385	    toolName?: string
386	  ): AuthorityGrant | null {
387	    for (const grant of this.grants) {
388	      // Check actor match
389	      if (grant.actor) {
390	        const actors = Array.isArray(grant.actor) ? grant.actor : [grant.actor];
391	        if (!actors.includes("*") && !actors.includes(actor)) {
392	          continue;
393	        }
394	      }
395	
396	      // Check domain match
397	      if (grant.executionDomain) {
398	        const domains = Array.isArray(grant.executionDomain)
399	          ? grant.executionDomain
400	          : [grant.executionDomain];
401	        if (!domains.includes("*") && !domains.includes(domain)) {
402	          continue;
403	        }
404	      }
405	
406	      // Check capability match
407	      const allowedCaps = grant.capabilities;
408	      const matchesCap =
409	        allowedCaps.includes("*") ||
410	        allowedCaps.includes(capabilityId) ||
411	        (toolName ? allowedCaps.includes(toolName) : false) ||
412	        (capabilityId === "fs_read" && allowedCaps.includes("file_read")) ||
413	        (capabilityId === "fs_write" && allowedCaps.includes("file_write")) ||
414	        (capabilityId === "proc_exec" && (allowedCaps.includes("command_execution") || allowedCaps.includes("run_command")));
415	
416	      if (!matchesCap) {
417	        continue;
418	      }
419	
420	      return grant;
421	    }
422	
423	    return null;
424	  }
425	}
