1	/**
2	 * Canonical Capabilities & Model-Visible Tool Registry
3	 * Nexus Issue #12 — WP-01 (INC-01, CAP-001..007, DEDUP-001..004)
4	 */
5	
6	import { ToolDefinition, ExecutionResult } from "../types.js";
7	
8	export type CapabilityBackend = "rust_rpc" | "ts_native" | "extension";
9	
10	export interface CanonicalCapability {
11	  /** Canonical capability identifier (e.g., 'fs_read', 'proc_exec') */
12	  id: string;
13	  /** Model-visible tool name matching LLM schemas (e.g., 'read_file', 'run_command') */
14	  modelToolName: string;
15	  /** Category of capability */
16	  category:
17	    | "fs"
18	    | "code_search"
19	    | "proc"
20	    | "vcs"
21	    | "net"
22	    | "lsp"
23	    | "browser"
24	    | "knowledge"
25	    | "skill"
26	    | "orchestration"
27	    | "extension"
28	    | string;
29	  /** Whether the capability performs mutating side effects */
30	  mutating: boolean;
31	  /** Human- and audit-readable side-effect contract */
32	  sideEffectContract: string;
33	  /** Backend execution engine type */
34	  backend: CapabilityBackend;
35	  /** Exact model tool definition (JSON schema) presented to LLMs */
36	  toolDefinition: ToolDefinition;
37	  /** Optional registered capability execution handler */
38	  handler?: CapabilityHandler;
39	}
40	
41	export type CapabilityHandler = (
42	  args: Record<string, any>,
43	  context: any
44	) => Promise<ExecutionResult>;
45	
46	export class CapabilityRegistry {
47	  private readonly capabilitiesByToolName = new Map<string, CanonicalCapability>();
48	  private readonly capabilitiesById = new Map<string, CanonicalCapability[]>();
49	
50	  constructor(capabilities: CanonicalCapability[] = []) {
51	    for (const cap of capabilities) {
52	      this.register(cap);
53	    }
54	  }
55	
56	  /**
57	   * Register a canonical capability.
58	   * Throws if a capability with the same modelToolName is already registered.
59	   */
60	  public register(capability: CanonicalCapability): void {
61	    if (!capability || !capability.id || !capability.modelToolName) {
62	      throw new Error("Invalid capability: id and modelToolName are required.");
63	    }
64	    if (this.capabilitiesByToolName.has(capability.modelToolName)) {
65	      throw new Error(`Duplicate capability registration: model tool '${capability.modelToolName}' is already registered.`);
66	    }
67	
68	    this.capabilitiesByToolName.set(capability.modelToolName, capability);
69	
70	    const list = this.capabilitiesById.get(capability.id) || [];
71	    list.push(capability);
72	    this.capabilitiesById.set(capability.id, list);
73	  }
74	
75	  /**
76	   * Unregister a capability by its tool name or canonical ID.
77	   */
78	  public unregister(toolNameOrId: string): boolean {
79	    const cap = this.capabilitiesByToolName.get(toolNameOrId);
80	    if (cap) {
81	      this.capabilitiesByToolName.delete(cap.modelToolName);
82	      const list = this.capabilitiesById.get(cap.id);
83	      if (list) {
84	        const filtered = list.filter((c) => c.modelToolName !== cap.modelToolName);
85	        if (filtered.length > 0) {
86	          this.capabilitiesById.set(cap.id, filtered);
87	        } else {
88	          this.capabilitiesById.delete(cap.id);
89	        }
90	      }
91	      return true;
92	    }
93	
94	    if (this.capabilitiesById.has(toolNameOrId)) {
95	      const caps = this.capabilitiesById.get(toolNameOrId)!;
96	      for (const c of caps) {
97	        this.capabilitiesByToolName.delete(c.modelToolName);
98	      }
99	      this.capabilitiesById.delete(toolNameOrId);
100	      return true;
101	    }
102	
103	    return false;
104	  }
105	
106	  /**
107	   * Retrieve capability by model tool name.
108	   */
109	  public getByToolName(toolName: string): CanonicalCapability | undefined {
110	    return this.capabilitiesByToolName.get(toolName);
111	  }
112	
113	  /**
114	   * Retrieve capability by canonical capability ID (returns first registered).
115	   */
116	  public getById(id: string): CanonicalCapability | undefined {
117	    const list = this.capabilitiesById.get(id);
118	    return list && list.length > 0 ? list[0] : undefined;
