1	/**
2	 * Application Core & Unified Execution Model (WP-10, INC-11, UI-001..UI-007)
3	 *
4	 * Implements the single authoritative Nexus application model governing
5	 * CLI, interactive REPL, and TUI presentations without parallel state machines.
6	 */
7	
8	import { EventEmitter } from "node:events";
9	import * as path from "node:path";
10	import * as fs from "node:fs";
11	import { AutonomousAgent } from "../agent.js";
12	import { HarnessConfig, ChatMessage } from "../types.js";
13	import { SessionManager, SessionData } from "../session.js";
14	import {
15	  DurableStateManager,
16	  DurableTaskState,
17	  DurablePlanPhase,
18	  DurableMilestoneRecord,
19	  DurableWorktreeBinding,
20	  TaskRecoveryOptions,
21	  TaskRecoveryResult,
22	  TaskLifecycleStatus,
23	} from "./state.js";
24	import { ExecutionSpine, ExecutionReceipt } from "./spine.js";
25	import { CapabilityRegistry } from "./capabilities.js";
26	import { AuthorityAdmissionEngine } from "./authority.js";
27	import { CandidateTracker, CandidateIdentity, ValidationReceipt } from "./candidate.js";
28	import { CheckpointManager } from "../checkpoint.js";
29	
30	export interface RunTaskOptions {
31	  json?: boolean;
32	  quiet?: boolean;
33	  onConfirm?: (tool: string, args: any) => Promise<boolean>;
34	  resumeTaskId?: string;
35	}
36	
37	export interface TaskExecutionResult {
38	  taskId: string;
39	  success: boolean;
40	  status: TaskLifecycleStatus;
41	  prompt: string;
42	  output: string;
43	  plan: DurablePlanPhase[];
44	  milestones: DurableMilestoneRecord[];
45	  candidateId?: string | null;
46	  candidateIdentity?: CandidateIdentity | null;
47	  validationReceipts: ValidationReceipt[];
48	  worktreeBinding?: DurableWorktreeBinding | null;
49	  tokenStats: {
50	    prompt: number;
51	    completion: number;
52	    total: number;
53	  };
54	  durationMs: number;
55	  error?: string;
56	  logs?: string[];
57	}
58	
59	export interface SlashCommandResult {
60	  command: string;
61	  subcommand?: string;
62	  success: boolean;
63	  output: string;
64	  data?: any;
65	  error?: string;
66	}
67	
68	export class ApplicationCore extends EventEmitter {
69	  private config: HarnessConfig;
70	  private agent: AutonomousAgent;
71	  private sessionManager: SessionManager;
72	  private checkpointManager: CheckpointManager;
73	  private stateManager: DurableStateManager;
74	
75	  constructor(config: HarnessConfig, agent?: AutonomousAgent) {
76	    super();
77	    this.config = { ...config };
78	    this.agent = agent || new AutonomousAgent(this.config);
79	    this.stateManager = this.agent.getStateManager();
80	    this.sessionManager = new SessionManager(undefined, () => this.agent.getWorkspacePathIdentity());
81	    this.checkpointManager = new CheckpointManager(this.config.workspace || process.cwd());
82	  }
83	
84	  public getAgent(): AutonomousAgent {
85	    return this.agent;
86	  }
87	
88	  public getConfig(): HarnessConfig {
89	    return this.config;
90	  }
91	
92	  public getTaskId(): string {
93	    return this.agent.getTaskId();
94	  }
95	
96	  public getSpine(): ExecutionSpine {
97	    return this.agent.getSpine();
98	  }
99	
100	  public getAuthorityEngine(): AuthorityAdmissionEngine {
101	    return this.agent.getAuthorityEngine();
102	  }
103	
104	  public getCandidateTracker(): CandidateTracker {
105	    return this.agent.getCandidateTracker();
106	  }
107	
108	  public getStateManager(): DurableStateManager {
109	    return this.stateManager;
110	  }
111	
112	  public getSessionManager(): SessionManager {
113	    return this.sessionManager;
114	  }
115	
116	  public getCheckpointManager(): CheckpointManager {
117	    return this.checkpointManager;
118	  }
119	
120	  public getActivePlan(): DurablePlanPhase[] {
121	    return this.agent.getActivePlan();
122	  }
123	
124	  public getMessages(): ChatMessage[] {
125	    return this.agent.getMessages();
126	  }
127	
128	  public getTokenStats(): { prompt: number; completion: number; total: number } {
129	    return this.agent.getTokenStats();
130	  }
131	
132	  public getTaskState(): DurableTaskState {
133	    const taskId = this.agent.getTaskId();
134	    if (this.stateManager.hasTaskState(taskId)) {
135	      try {
136	        const state = this.stateManager.loadTaskState(taskId);
137	        if (!state.candidateId && state.validationReceipts && state.validationReceipts.length > 0) {
138	          state.candidateId = state.validationReceipts[state.validationReceipts.length - 1].candidateId;
139	        }
140	        return state;
141	      } catch {}
142	    }
143	    return this.agent.checkpointDurableState();
144	  }
145	
146	  public getActiveValidationReceipt(): ValidationReceipt | null {
147	    const fromAgent = this.agent.getActiveValidationReceipt();
148	    if (fromAgent) return fromAgent;
149	    const taskId = this.agent.getTaskId();
150	    if (this.stateManager.hasTaskState(taskId)) {
151	      try {
152	        const state = this.stateManager.loadTaskState(taskId);
153	        if (state.validationReceipts && state.validationReceipts.length > 0) {
154	          return state.validationReceipts[state.validationReceipts.length - 1];
155	        }
156	      } catch {}
157	    }
158	    return null;
159	  }
160	
161	  /**
162	   * Executes a task through the unified execution spine and durable state lifecycle (UI-001, UI-002, UI-003).
163	   */
164	  public async runTask(prompt: string, options: RunTaskOptions = {}): Promise<TaskExecutionResult> {
165	    const startTime = Date.now();
166	    const taskId = this.agent.getTaskId();
167	
168	    if (options.resumeTaskId) {
169	      await this.recoverTask(options.resumeTaskId);
170	    }
171	
172	    this.emit("task:start", {
173	      taskId,
174	      prompt,
175	      timestamp: new Date().toISOString(),
176	    });
177	
178	    const capturedLogs: string[] = [];
179	    const shouldCapture = Boolean(options.json || options.quiet);
180	
181	    // Intercept stdout/console when machine-readable JSON is requested
182	    const originalLog = console.log;
183	    const originalWarn = console.warn;
184	    const originalError = console.error;
185	    const originalStdoutWrite = process.stdout.write.bind(process.stdout);
186	
187	    if (shouldCapture) {
188	      console.log = (...args: any[]) => {
189	        capturedLogs.push(args.map((a) => (typeof a === "string" ? a : JSON.stringify(a))).join(" "));
190	      };
191	      console.warn = (...args: any[]) => {
192	        capturedLogs.push("[WARN] " + args.map((a) => (typeof a === "string" ? a : JSON.stringify(a))).join(" "));
193	      };
194	      console.error = (...args: any[]) => {
195	        capturedLogs.push("[ERROR] " + args.map((a) => (typeof a === "string" ? a : JSON.stringify(a))).join(" "));
196	      };
197	    }
198	
199	    let taskError: Error | undefined;
200	    try {
201	      await this.agent.run(prompt, options.onConfirm);
202	    } catch (err: any) {
203	      taskError = err;
204	    } finally {
205	      if (shouldCapture) {
206	        console.log = originalLog;
207	        console.warn = originalWarn;
208	        console.error = originalError;
209	      }
210	    }
211	
212	    // Capture durable task state snapshot
213	    let durableState: DurableTaskState;
214	    try {
215	      durableState = this.agent.checkpointDurableState("Task execution finished");
216	    } catch {
217	      durableState = this.getTaskState();
218	    }
219	
220	    // Persist session envelope synchronously
221	    const messages = this.agent.getMessages();
222	    this.sessionManager.saveSession({
223	      id: taskId,
224	      taskId,
225	      sessionId: taskId,
226	      title: prompt.slice(0, 60).replace(/\n/g, " "),
227	      createdAt: durableState.createdAt || new Date().toISOString(),
228	      updatedAt: new Date().toISOString(),
229	      workspace: this.config.workspace,
230	      model: this.config.model,
231	      status: taskError ? "failed" : durableState.status || "completed",
232	      messages,
233	      tokenStats: this.agent.getTokenStats(),
234	      activePlan: durableState.activePlan,
235	      milestones: durableState.milestones,
236	      candidateId: durableState.candidateId,
237	      validationReceipts: durableState.validationReceipts,
238	      worktreeBinding: durableState.worktreeBinding,
239	    }, this.agent.getWorkspacePathIdentity());
240	
241	    // Extract last assistant output
242	    let outputText = "";
243	    for (let i = messages.length - 1; i >= 0; i--) {
244	      if (messages[i].role === "assistant" && messages[i].content) {
245	        const c = messages[i].content;
246	        outputText = typeof c === "string" ? c : JSON.stringify(c);
247	        break;
248	      }
249	    }
250	
251	    const durationMs = Date.now() - startTime;
252	    const success = !taskError && durableState.status !== "failed" && durableState.status !== "interrupted";
253	
254	    const result: TaskExecutionResult = {
255	      taskId,
256	      success,
257	      status: taskError ? "failed" : durableState.status,
258	      prompt,
259	      output: outputText,
260	      plan: durableState.activePlan || [],
261	      milestones: durableState.milestones || [],
262	      candidateId: durableState.candidateId || null,
263	      candidateIdentity: durableState.candidateIdentity || null,
264	      validationReceipts: durableState.validationReceipts || [],
265	      worktreeBinding: durableState.worktreeBinding || null,
266	      tokenStats: this.agent.getTokenStats(),
267	      durationMs,
268	      error: taskError ? taskError.message : undefined,
269	      logs: shouldCapture ? capturedLogs : undefined,
270	    };
271	
272	    this.emit("task:end", result);
273	    return result;
274	  }
275	
276	  /**
277	   * Executes an explicit direct shell / operator command through the ExecutionSpine (ACT-004, AUTH-001).
278	   * Formally logs execution with 'operator' actor identity.
279	   */
280	  public async executeOperatorCommand(command: string): Promise<ExecutionReceipt> {
281	    const spine = this.agent.getSpine();
282	    const effectiveTaskId = this.agent.getTaskId();
283	    const receipt = await spine.execute(
284	      {
285	        toolName: "run_command",
286	        args: { command },
287	        actor: "operator",
288	        executionDomain: "operator_direct_shell",
289	        taskId: effectiveTaskId,
290	      },
291	      {
292	        workspaceRoot: this.config.workspace,
293	        readOnly: this.config.readOnly,
294	        bridge: this.agent.getBridge(),
295	      }
296	    );
297	
298	    this.emit("operator:command", { command, receipt });
299	    return receipt;
300	  }
301	
302	  /**
303	   * Unified slash command router conforming to UI-006 and ACT-004.
304	   */
305	  public async executeSlashCommand(cmdStr: string, argStr: string = ""): Promise<SlashCommandResult> {
306	    const cleanCmd = cmdStr.startsWith("/") ? cmdStr.slice(1).trim().toLowerCase() : cmdStr.trim().toLowerCase();
307	    const args = argStr.trim().split(/\s+/).filter(Boolean);
308	    const subCmd = args[0]?.toLowerCase();
309	
310	    switch (cleanCmd) {
311	      case "plan": {
312	        if (subCmd === "add") {
313	          const phaseName = args.slice(1).join(" ");
314	          if (!phaseName) {
315	            return { command: "plan", success: false, output: "Usage: /plan add <phase description>", error: "Missing phase description" };
316	          }
317	          const plan = [...this.agent.getActivePlan(), { name: phaseName, status: "pending" }];
318	          this.agent.setActivePlan(plan);
319	          this.agent.checkpointDurableState("Added plan phase");
320	          this.emit("plan:change", { taskId: this.getTaskId(), phases: plan });
321	          return { command: "plan", subcommand: "add", success: true, output: `Added phase: ${phaseName}`, data: plan };
322	        } else if (subCmd === "done" || subCmd === "complete") {
323	          const idx = parseInt(args[1], 10) - 1;
324	          const plan = [...this.agent.getActivePlan()];
325	          if (isNaN(idx) || idx < 0 || idx >= plan.length) {
326	            return { command: "plan", success: false, output: `Invalid phase index. Valid range: 1..${plan.length}`, error: "Index out of range" };
327	          }
328	          plan[idx] = { ...plan[idx], status: "completed" };
329	          this.agent.setActivePlan(plan);
330	          this.stateManager.recordMilestone(this.getTaskId(), {
331	            name: plan[idx].name,
332	            phaseIndex: idx,
333	            evidenceSummary: plan[idx].detail || "Marked complete by operator",
334	          });
335	          this.emit("plan:change", { taskId: this.getTaskId(), phases: plan });
336	          return { command: "plan", subcommand: "done", success: true, output: `Phase ${idx + 1} completed: ${plan[idx].name}`, data: plan };
337	        } else if (subCmd === "start") {
338	          const idx = parseInt(args[1], 10) - 1;
339	          const plan = [...this.agent.getActivePlan()];
340	          if (isNaN(idx) || idx < 0 || idx >= plan.length) {
341	            return { command: "plan", success: false, output: `Invalid phase index. Valid range: 1..${plan.length}`, error: "Index out of range" };
342	          }
343	          plan[idx] = { ...plan[idx], status: "in_progress" };
344	          this.agent.setActivePlan(plan);
345	          this.agent.checkpointDurableState("Started plan phase");
346	          this.emit("plan:change", { taskId: this.getTaskId(), phases: plan });
347	          return { command: "plan", subcommand: "start", success: true, output: `Phase ${idx + 1} in progress: ${plan[idx].name}`, data: plan };
348	        } else if (subCmd === "clear") {
349	          this.agent.setActivePlan([]);
350	          this.agent.checkpointDurableState("Cleared plan");
351	          this.emit("plan:change", { taskId: this.getTaskId(), phases: [] });
352	          return { command: "plan", subcommand: "clear", success: true, output: "Plan cleared.", data: [] };
353	        } else {
354	          const plan = this.agent.getActivePlan();
355	          return { command: "plan", subcommand: "list", success: true, output: JSON.stringify(plan, null, 2), data: plan };
356	        }
357	      }
358	
359	      case "status": {
360	        const state = this.getTaskState();
361	        const info = {
362	          taskId: state.taskId,
363	          status: state.status,
364	          model: this.config.model,
365	          workspace: this.config.workspace,
366	          readOnly: Boolean(this.config.readOnly),
367	          candidateId: state.candidateId || null,
368	          validationReceiptsCount: (state.validationReceipts || []).length,
369	          planPhasesCount: (state.activePlan || []).length,
370	          worktree: state.worktreeBinding ? state.worktreeBinding.worktreePath : null,
371	          tokenStats: this.getTokenStats(),
372	        };
373	        return { command: "status", success: true, output: JSON.stringify(info, null, 2), data: info };
374	      }
375	
376	      case "recover": {
377	        const targetId = args[0] || this.getTaskId();
378	        try {
379	          const rec = await this.recoverTask(targetId);
380	          return {
381	            command: "recover",
382	            success: rec.success,
383	            output: `Recovered task ${targetId}: candidate=${rec.candidateStatus}, worktree=${rec.worktreeStatus}, invalidatedReceipts=${rec.invalidatedReceiptCount}`,
384	            data: rec,
385	          };
386	        } catch (err: any) {
387	          return { command: "recover", success: false, output: `Failed to recover task ${targetId}: ${err.message}`, error: err.message };
388	        }
389	      }
390	
391	      case "checkpoint": {
392	        const name = args.join(" ") || `Checkpoint ${new Date().toISOString()}`;
393	        try {
394	          const cp = this.checkpointManager.createCheckpoint(name);
395	          return { command: "checkpoint", success: true, output: `Created checkpoint: ${cp.id} (${name})`, data: cp };
396	        } catch (err: any) {
397	          return { command: "checkpoint", success: false, output: `Failed to create checkpoint: ${err.message}`, error: err.message };
398	        }
399	      }
400	
401	      case "worktrees": {
402	        const wts = this.agent.getWorktreeManager().listWorktrees();
403	        return { command: "worktrees", success: true, output: JSON.stringify(wts, null, 2), data: wts };
404	      }
405	
406	      case "tokens": {
407	        const stats = this.getTokenStats();
408	        return { command: "tokens", success: true, output: JSON.stringify(stats, null, 2), data: stats };
409	      }
410	
411	      default:
412	        return { command: cleanCmd, success: false, output: `Unknown slash command: /${cleanCmd}`, error: "Unknown command" };
413	    }
414	  }
415	
416	  /**
417	   * Recovers a task state through the underlying agent and state manager.
418	   */
419	  public async recoverTask(taskId: string, options: TaskRecoveryOptions = {}): Promise<TaskRecoveryResult> {
420	    const recoveryResult = await this.agent.recoverFromTaskState(taskId, options);
421	    this.emit("task:recovered", recoveryResult);
422	    return recoveryResult;
423	  }
424	
425	  /**
426	   * Checkpoints state to durable persistence.
427	   */
428	  public checkpointState(notes?: string): DurableTaskState {
429	    const taskId = this.agent.getTaskId();
430	    let prevCandidateId: string | null = null;
431	    let prevIdentity: CandidateIdentity | null = null;
432	    if (this.stateManager.hasTaskState(taskId)) {
433	      try {
434	        const existing = this.stateManager.loadTaskState(taskId);
435	        prevCandidateId = existing.candidateId || null;
436	        prevIdentity = existing.candidateIdentity || null;
437	      } catch {}
438	    }
439	
440	    const state = this.agent.checkpointDurableState(notes);
441	    if (!state.candidateId && prevCandidateId) {
442	      state.candidateId = prevCandidateId;
443	      state.candidateIdentity = prevIdentity;
444	      this.stateManager.saveTaskState(state);
445	    }
446	    this.emit("state:checkpoint", state);
447	    return state;
448	  }
449	
450	  public shutdown(): void {
451	    this.agent.shutdown();
452	  }
453	}
