108	  endpointOrUrl?: string | null,
109	  policy?: EgressPolicy
110	): DestinationTrustBoundary {
111	  if (!endpointOrUrl || endpointOrUrl === "local" || endpointOrUrl === "host" || endpointOrUrl === "in-memory") {
112	    return "HOST_LOCAL";
113	  }
114	
115	  const trimmed = endpointOrUrl.trim();
116	  if (trimmed.startsWith("/") || trimmed.startsWith("./") || trimmed.startsWith("file:") || trimmed.startsWith("unix:")) {
117	    return "HOST_LOCAL";
118	  }
