173	export function calculateShannonEntropy(str: string): number {
174	  if (!str) return 0;
175	  const len = str.length;
176	  const frequencies = new Map<string, number>();
177	  for (let i = 0; i < len; i++) {
178	    const ch = str[i];
179	    frequencies.set(ch, (frequencies.get(ch) || 0) + 1);
180	  }
181	  let entropy = 0;
182	  for (const count of frequencies.values()) {
183	    const p = count / len;
184	    entropy -= p * Math.log2(p);
185	  }
186	  return entropy;
187	}
