232	    },
233	    {
234	      name: "AWS_SECRET_KEY_PAIR",
235	      regex: /(?:(?:aws_secret_access_key|secret_key)\s*[:=]\s*["']?)([a-zA-Z0-9/+=]{40})(?:["']?)/gi,
236	    },
237	  ];
238	
239	  constructor(policy?: EgressPolicy) {
240	    if (policy) {
241	      this.policy = policy;
242	    }
243	  }
244	
245	  public static getGlobalInstance(): InformationFlowBoundary {
246	    if (!InformationFlowBoundary.globalInstance) {
247	      InformationFlowBoundary.globalInstance = new InformationFlowBoundary();
248	    }
249	    return InformationFlowBoundary.globalInstance;
250	  }
251	
252	  public static setGlobalInstance(instance: InformationFlowBoundary): void {
253	    InformationFlowBoundary.globalInstance = instance;
254	  }
255	
256	  public setPolicy(policy: EgressPolicy): void {
257	    this.policy = policy;
258	  }
259	
260	  public getPolicy(): EgressPolicy {
261	    return this.policy;
262	  }
263	
264	  /**
265	   * Classify sensitive data within a text string (DATA-001, DATA-002, DATA-003, DATA-004).
266	   */
267	  public classifyText(text: string): ClassifiedSecret[] {
268	    if (!text || typeof text !== "string") return [];
269	
270	    const classified: ClassifiedSecret[] = [];
271	    const seenSecrets = new Set<string>();
272	
273	    // 1. Explicit Operator Classifications (DATA-002: Category 1)
274	    if (this.policy.explicitSecrets && this.policy.explicitSecrets.length > 0) {
275	      for (const explicit of this.policy.explicitSecrets) {
276	        if (explicit && text.includes(explicit) && !seenSecrets.has(explicit)) {
277	          seenSecrets.add(explicit);
278	          classified.push({
279	            secret: explicit,
280	            classificationType: "OPERATOR_EXPLICIT",
281	            classifierId: "operator:policy",
282	            confidence: 1.0,
283	            patternName: "EXPLICIT_SECRET",
284	          });
285	        }
286	      }
287	    }
288	
289	    // 2. Deterministic High-Confidence Patterns (DATA-002: Category 2)
290	    for (const { name, regex } of InformationFlowBoundary.DETERMINISTIC_PATTERNS) {
291	      const re = new RegExp(regex.source, regex.flags);
292	      let match: RegExpExecArray | null;
293	      while ((match = re.exec(text)) !== null) {
294	        const fullMatch = match[0];
295	        // If capture group exists (e.g. Bearer token), extract captured secret, else fullMatch
296	        const secretVal = match[1] && typeof match[1] === "string" ? match[1] : fullMatch;
297	        if (secretVal.length >= 8 && !secretVal.startsWith("[NEXUS_SEC_REF_") && !seenSecrets.has(secretVal)) {
298	          seenSecrets.add(secretVal);
299	          classified.push({
300	            secret: secretVal,
301	            classificationType: "PATTERN_DETERMINISTIC",
302	            classifierId: `regex:${name.toLowerCase()}`,
303	            confidence: 0.95,
304	            patternName: name,
305	          });
306	        }
307	      }
308	    }
309	
310	    // 3. Contextual / Heuristic Classifications (DATA-002: Category 3, DATA-003: Preserves LHS identifiers)
311	    for (const { name, regex } of InformationFlowBoundary.CONTEXTUAL_PATTERNS) {
312	      const re = new RegExp(regex.source, regex.flags);
313	      let match: RegExpExecArray | null;
314	      while ((match = re.exec(text)) !== null) {
315	        const secretVal = match[1];
316	        if (
317	          secretVal &&
318	          secretVal.length >= 8 &&
319	          !secretVal.startsWith("[NEXUS_SEC_REF_") &&
320	          !seenSecrets.has(secretVal)
321	        ) {
322	          // Avoid matching obvious non-secrets / placeholders
323	          const lower = secretVal.toLowerCase();
324	          if (lower === "password" || lower === "changeme" || lower === "your_api_key_here") {
325	            continue;
326	          }
327	          seenSecrets.add(secretVal);
328	          classified.push({
329	            secret: secretVal,
330	            classificationType: "CONTEXTUAL_HEURISTIC",
331	            classifierId: `heuristic:${name.toLowerCase()}`,
332	            confidence: 0.75,
333	            patternName: name,
334	          });
335	        }
336	      }
337	    }
338	
339	    // 4. High-Entropy Token Detection (DATA-002: Category 4 / DATA-004)
340	    // Check individual non-whitespace tokens length >= 20 with high Shannon entropy
341	    const tokens = text.split(/[\s,;'"()\[\]{}]+/);
342	    for (const tok of tokens) {
343	      if (tok.length >= 20 && tok.length <= 128 && !tok.startsWith("[NEXUS_SEC_REF_") && !seenSecrets.has(tok)) {
344	        if (/^[a-zA-Z0-9+/=_-]+$/.test(tok)) {
345	          const entropy = calculateShannonEntropy(tok);
346	          // Scaled entropy threshold: >= 4.0 for length 20-31, >= 4.5 for length >= 32
347	          const threshold = tok.length < 32 ? 4.0 : 4.5;
348	          if (entropy >= threshold) {
349	            seenSecrets.add(tok);
350	            classified.push({
351	              secret: tok,
352	              classificationType: "UNCERTAIN",
353	              classifierId: "entropy:shannon_token",
354	              confidence: 0.55,
355	              patternName: "HIGH_ENTROPY_STRING",
356	            });
357	          }
358	        }
359	      }
360	    }
361	
362	    return classified;
363	  }
364	
365	  /**
366	   * Irreversibly redact classified values from durable telemetry before it is written.
367	   * This uses the same DATA-001 classifier as egress protection and deliberately
368	   * does not create reversible vault references (DISC-005).
369	   */
370	  public redactForTelemetry<T>(value: T): T {
371	    return this.redactClassifiedValue(value);
372	  }
373	
374	  /**
375	   * Irreversibly redact classified values from durable application state.
376	   * This preserves the accepted classifier and redaction semantics but does not
377	   * make the value recoverable as a credential store would.
378	   */
379	  public redactForDurablePersistence<T>(value: T): T {
380	    return this.redactClassifiedValue(value);
381	  }
382	
383	  private redactClassifiedValue<T>(value: T): T {
384	    const visit = (item: any): any => {
385	      if (typeof item === "string") {
386	        let sanitized = item;
387	        for (const secret of this.classifyText(item)) {
388	          sanitized = sanitized.replaceAll(secret.secret, `[REDACTED:${secret.patternName || "SECRET"}]`);
389	        }
390	        return sanitized;
391	      }
392	      if (Array.isArray(item)) return item.map(visit);
393	      if (item && typeof item === "object") {
394	        const sanitized: Record<string, any> = {};
395	        for (const [key, nested] of Object.entries(item)) {
396	          sanitized[visit(key)] = visit(nested);
397	        }
398	        return sanitized;
399	      }
400	      return item;
401	    };
402	
403	    const recursivelySanitized = visit(value);
404	    // Run the canonical classifier once over the serialized structure too. This
405	    // preserves contextual policies (for example, api_key=REDACTED whose signal
406	    // spans an object key and its nested string value.
407	    const serialized = JSON.stringify(recursivelySanitized);
408	    if (serialized === undefined) throw new Error("Telemetry payload is not JSON serializable");
409	    let sanitizedSerialized = serialized;
410	    for (const secret of this.classifyText(serialized)) {
411	      sanitizedSerialized = sanitizedSerialized.replaceAll(secret.secret, `[REDACTED:${secret.patternName || "SECRET"}]`);
412	    }
413	    return JSON.parse(sanitizedSerialized) as T;
414	  }
415	
416	  /**
417	   * Generates a cryptographically unguessable, task-scoped reference (REHYD-001, REHYD-002).
418	   */
419	  public generateToken(
420	    secret: string,
421	    taskId: string,
422	    sessionId: string,
423	    sourceBoundary: DestinationTrustBoundary,
424	    targetBoundary: DestinationTrustBoundary
425	  ): string {
426	    const scopeKey = `${taskId}:${secret}`;
427	    const existing = this.secretToTokenMap.get(scopeKey);
428	    if (existing) {
429	      return existing;
430	    }
431	
432	    // 128 bits of cryptographic randomness (REHYD-001)
433	    const nonce = randomBytes(16).toString("hex");
434	    const token = `[NEXUS_SEC_REF_${nonce}]`;
435	
436	    const record: ReversibleTokenRecord = {
437	      token,
438	      secret,
439	      taskId: taskId || "default_task",
440	      sessionId: sessionId || "default_session",
441	      sourceBoundary,
442	      targetBoundary,
443	      createdAt: Date.now(),
444	      rehydratedCount: 0,
445	    };
446	
447	    this.tokenVault.set(token, record);
448	    this.secretToTokenMap.set(scopeKey, token);
449	    return token;
450	  }
451	
452	  /**
453	   * Evaluates outbound payload against destination trust boundary (DEST-001, DEST-002, DISC-001..005, FAIL-003).
454	   */
455	  public evaluateEgress(
456	    payload: string | Record<string, any> | any[],
457	    destinationEndpointOrUrl?: string | null,
458	    context?: EgressEvaluationContext
459	  ): EgressEvaluationResult {
460	    // FAIL-CLOSED on simulated or internal failure (FAIL-003)
461	    if (context?.isSimulatedFailure) {
462	      return {
463	        allowed: false,
464	        destinationBoundary: "EXTERNAL_PUBLIC",
465	        transitionCrossesBoundary: true,
466	        quarantinedCount: 0,
467	        classifiedSecrets: [],
468	        reason: "Security Gate Violation [FAIL-003]: Simulated egress classification failure; failing closed.",
469	      };
470	    }
471	
472	    try {
473	      const destBoundary = classifyDestination(destinationEndpointOrUrl, this.policy);
474	      const sourceBoundary = context?.sourceBoundary || "HOST_LOCAL";
475	      const crossesBoundary = isEgressTransition(sourceBoundary, destBoundary);
476	
477	      // If within same high-trust boundary and no transition to external, allow without quarantine
478	      if (!crossesBoundary && destBoundary === "HOST_LOCAL") {
479	        return {
480	          allowed: true,
481	          destinationBoundary: destBoundary,
482	          transitionCrossesBoundary: false,
483	          quarantinedCount: 0,
484	          sanitizedPayload: payload,
485	          sanitizedText: typeof payload === "string" ? payload : JSON.stringify(payload),
486	          classifiedSecrets: [],
487	        };
488	      }
489	
490	      // Convert payload to string for inspection
491	      const rawText = typeof payload === "string" ? payload : JSON.stringify(payload);
492	      const classifiedSecrets = this.classifyText(rawText);
493	
494	      // If no secrets detected, allow
495	      if (classifiedSecrets.length === 0) {
496	        return {
497	          allowed: true,
498	          destinationBoundary: destBoundary,
499	          transitionCrossesBoundary: crossesBoundary,
500	          quarantinedCount: 0,
501	          sanitizedPayload: payload,
502	          sanitizedText: rawText,
503	          classifiedSecrets: [],
504	        };
505	      }
506	
507	      // If secrets exist and disclosure is NOT explicitly authorized, apply protection (DISC-001)
508	      if (context?.disclosureAuthorized === true) {
509	        // Explicit disclosure authorized by policy
510	        return {
511	          allowed: true,
512	          destinationBoundary: destBoundary,
513	          transitionCrossesBoundary: crossesBoundary,
514	          quarantinedCount: 0,
515	          sanitizedPayload: payload,
516	          sanitizedText: rawText,
517	          classifiedSecrets,
518	        };
519	      }
520	
521	      // Determine protection mode (DISC-005)
522	      const mode = context?.preferredProtectionMode || "REVERSIBLE_TOKENIZATION";
523	      let sanitizedText = rawText;
524	      let quarantinedCount = 0;
525	
526	      const taskId = context?.taskId || "default_task";
527	      const sessionId = context?.sessionId || "default_session";
528	
529	      for (const item of classifiedSecrets) {
530	        const secret = item.secret;
531	        if (!sanitizedText.includes(secret)) continue;
532	
533	        let replacement: string;
534	        if (mode === "IRREVERSIBLE_REDACTION") {
535	          replacement = `[REDACTED:${item.patternName || "SECRET"}]`;
536	        } else if (mode === "ENCRYPTION") {
537	          // Reversible encrypted token simulation
538	          replacement = this.generateToken(secret, taskId, sessionId, sourceBoundary, destBoundary);
539	        } else {
540	          // REVERSIBLE_TOKENIZATION (Default)
541	          replacement = this.generateToken(secret, taskId, sessionId, sourceBoundary, destBoundary);
542	        }
543	
544	        sanitizedText = sanitizedText.replaceAll(secret, replacement);
545	        quarantinedCount++;
546	      }
547	
548	      // Reconstruct payload in original format
549	      let sanitizedPayload: any = sanitizedText;
550	      if (typeof payload !== "string") {
551	        try {
552	          sanitizedPayload = JSON.parse(sanitizedText);
553	        } catch {
554	          sanitizedPayload = sanitizedText;
555	        }
556	      }
557	
558	      return {
559	        allowed: true,
560	        destinationBoundary: destBoundary,
561	        transitionCrossesBoundary: crossesBoundary,
562	        quarantinedCount,
563	        sanitizedPayload,
564	        sanitizedText,
565	        classifiedSecrets,
566	      };
567	    } catch (err: any) {
568	      // Fail closed on unhandled error (FAIL-003)
569	      return {
570	        allowed: false,
571	        destinationBoundary: "EXTERNAL_PUBLIC",
572	        transitionCrossesBoundary: true,
573	        quarantinedCount: 0,
574	        classifiedSecrets: [],
575	        reason: `Egress Classification Failure [FAIL-003]: ${err?.message || "Internal error in egress evaluator"}. Failing closed.`,
576	      };
577	    }
578	  }
579	
580	  /**
581	   * Rehydrates quarantined tokens for authorized local tool execution (REHYD-001..005, DISC-004).
582	   *
583	   * Invariants:
584	   * - Token possession alone != authority (REHYD-003). Requires isAuthorizedSink === true.
585	   * - Tokens are scoped to owning taskId (REHYD-002). Cross-task rehydration fails closed.
586	   * - Forged, stale, or unknown tokens remain completely inert (REHYD-005).
587	   */
588	  public rehydrate(
589	    payload: any,
590	    context: RehydrationContext
591	  ): RehydrationResult {
592	    let rehydratedCount = 0;
593	    let inertCount = 0;
594	
595	    const serialize = (val: any): string => (typeof val === "string" ? val : JSON.stringify(val));
596	    const raw = serialize(payload);
597	
598	    // Matches both [NEXUS_SEC_REF_<hex>] and legacy [SECRET_REF_<id>]
599	    const TOKEN_REGEX = /\[(?:NEXUS_SEC_REF_[a-f0-9]{32}|SECRET_REF_[a-zA-Z0-9_\-]+)\]/g;
600	
601	    let restoredText = raw.replace(TOKEN_REGEX, (token) => {
602	      // Rule 1: Possession != Authority (REHYD-003)
603	      if (!context.isAuthorizedSink) {
604	        inertCount++;
605	        return token; // Inert
606	      }
607	
608	      // Rule 2: Token must exist in vault (REHYD-005)
609	      const record = this.tokenVault.get(token);
610	      if (!record) {
611	        inertCount++;
612	        return token; // Inert
613	      }
614	
615	      // Rule 3: Task & Session Scoping (REHYD-002, FINDING-WP05-001)
616	      // If the token is scoped to a taskId, rehydration context MUST supply the matching taskId
617	      if (record.taskId && (!context.taskId || record.taskId !== context.taskId)) {
618	        inertCount++;
619	        return token; // Cross-task or un-scoped token remains inert
620	      }
621	
622	      // If the token is scoped to a sessionId, rehydration context cannot mismatch
623	      if (record.sessionId && context.sessionId && record.sessionId !== context.sessionId) {
624	        inertCount++;
625	        return token; // Cross-session token remains inert
626	      }
627	
628	      // Authorized Rehydration
629	      record.rehydratedCount++;
630	      rehydratedCount++;
631	      return record.secret;
632	    });
633	
634	    let rehydratedPayload: any = restoredText;
635	    if (typeof payload !== "string") {
636	      try {
637	        rehydratedPayload = JSON.parse(restoredText);
638	      } catch {
639	        rehydratedPayload = restoredText;
640	      }
641	    }
642	
643	    return {
644	      rehydrated: rehydratedPayload,
645	      rehydratedCount,
646	      inertCount,
647	    };
648	  }
649	
650	  /**
651	   * Directly registers a token mapping in the vault (used by SecretsVault migration).
652	   */
653	  public registerToken(record: ReversibleTokenRecord): void {
654	    this.tokenVault.set(record.token, record);
655	    this.secretToTokenMap.set(`${record.taskId}:${record.secret}`, record.token);
656	  }
657	
658	  public getTokenRecord(token: string): ReversibleTokenRecord | undefined {
659	    return this.tokenVault.get(token);
660	  }
661	
662	  public getVaultSize(): number {
663	    return this.tokenVault.size;
664	  }
665	
666	  public clear(): void {
667	    this.tokenVault.clear();
668	    this.secretToTokenMap.clear();
669	  }
670	}
