2	import * as path from "node:path";
3	import * as fs from "node:fs";
4	import * as os from "node:os";
5	
6	export type SandboxMode = "auto" | "bwrap" | "docker" | "none";
7	
8	export interface SandboxOptions {
9	  mode?: SandboxMode;
10	  readOnlyHost?: boolean;
11	  network?: boolean;
12	  shell?: string;
13	  customBwrapArgs?: string[];
14	}
15	
