        cmd.args(["/C", &args.command]);
    }
    #[cfg(not(windows))]
    cmd.args(["-c", &args.command]);

    cmd.current_dir(&working_dir)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());

    let mut child = cmd.spawn().map_err(|e| {
        format!("Failed to execute '{}' via {shell_name}: {e}", args.command)
    })?;

