45	export class PluginManager {
46	  private workspace: string;
47	  private plugins: Map<string, PluginHooks> = new Map();
48	  private customToolsMap: Map<string, (args: Record<string, any>) => Promise<ExecutionResult>> = new Map();
49	  private customToolDefs: ToolDefinition[] = [];
50	
51	  constructor(workspace: string) {
52	    this.workspace = path.resolve(workspace);
53	  }
54	
55	  public async loadPlugins(): Promise<void> {
56	    this.plugins.clear();
57	    this.customToolsMap.clear();
58	    this.customToolDefs = [];
59	
60	    const pluginDirs = [
61	      path.join(this.workspace, ".nexus", "plugins"),
62	      path.join(this.workspace, "plugins"),
63	      path.join(os.homedir(), ".nexus", "plugins"),
64	      path.join(os.homedir(), ".config", "nexus", "plugins"),
65	      path.join(os.homedir(), ".config", "opencode", "plugins"),
66	    ];
67	
68	    for (const dir of pluginDirs) {
69	      if (!fs.existsSync(dir)) continue;
70	
71	      try {
72	        const files = fs.readdirSync(dir);
73	        for (const file of files) {
74	          if (file.endsWith(".js") || file.endsWith(".mjs")) {
75	            const pluginPath = path.join(dir, file);
76	            await this.loadPluginFile(pluginPath);
77	          }
78	        }
79	      } catch {
80	        // Ignore read errors
81	      }
