85	  private async loadPluginFile(filePath: string): Promise<void> {
86	    try {
87	      const fileUrl = pathToFileURL(filePath).href;
88	      const mod = await import(fileUrl);
89	      const plugin: PluginHooks = mod.default || mod;
90	
91	      if (plugin && typeof plugin === "object" && plugin.name) {
92	        this.plugins.set(plugin.name, plugin);
93	
94	        if (Array.isArray(plugin.customTools)) {
95	          for (const ct of plugin.customTools) {
96	            if (ct.definition?.function?.name && typeof ct.handler === "function") {
97	              this.customToolDefs.push(ct.definition);
98	              this.customToolsMap.set(ct.definition.function.name, ct.handler);
99	            }
100	          }
101	        }
102	      }
103	    } catch {
104	      // Ignore plugins that fail to load
105	    }
106	  }
107	
108	  public registerPlugin(plugin: PluginHooks): void {
109	    if (plugin && plugin.name) {
110	      this.plugins.set(plugin.name, plugin);
111	      if (Array.isArray(plugin.customTools)) {
112	        for (const ct of plugin.customTools) {
113	          if (ct.definition?.function?.name && typeof ct.handler === "function") {
114	            this.customToolDefs.push(ct.definition);
115	            this.customToolsMap.set(ct.definition.function.name, ct.handler);
116	          }
117	        }
118	      }
119	    }
120	  }
121	
122	  public getCustomToolDefinitions(): ToolDefinition[] {
123	    return this.customToolDefs;
124	  }
125	
126	  public isCustomTool(toolName: string): boolean {
127	    return this.customToolsMap.has(toolName);
128	  }
129	
130	  public async executeCustomTool(toolName: string, args: Record<string, any>): Promise<ExecutionResult> {
131	    const handler = this.customToolsMap.get(toolName);
132	    if (!handler) {
133	      return { success: false, output: "", error: `Custom tool not found: ${toolName}` };
134	    }
135	    return handler(args);
136	  }
137	
138	  /**
139	   * Execute tool through the pre-tool and post-tool middleware pipeline (Candidate #41)
140	   */
141	  public async executeToolPipeline(
142	    toolName: string,
143	    initialArgs: Record<string, any>,
144	    coreExecutor: (args: Record<string, any>) => Promise<ExecutionResult>
145	  ): Promise<ExecutionResult> {
146	    const preMiddlewares: Array<NonNullable<PluginHooks["preToolExecution"]>> = [];
147	    const postMiddlewares: Array<NonNullable<PluginHooks["postToolExecution"]>> = [];
148	
149	    for (const plugin of this.plugins.values()) {
150	      if (plugin.preToolExecution) {
151	        preMiddlewares.push(plugin.preToolExecution);
152	      }
153	      if (plugin.postToolExecution) {
154	        postMiddlewares.push(plugin.postToolExecution);
155	      }
156	    }
157	
158	    const dispatch = async (idx: number, currentArgs: Record<string, any>): Promise<ExecutionResult> => {
159	      if (idx < preMiddlewares.length) {
160	        const mw = preMiddlewares[idx];
161	        return mw(
162	          { toolName, args: currentArgs, workspace: this.workspace },
163	          async (nextArgs) => dispatch(idx + 1, nextArgs || currentArgs)
164	        );
165	      }
166	      return coreExecutor(currentArgs);
167	    };
168	
169	    let result = await dispatch(0, initialArgs);
170	
171	    for (const postMw of postMiddlewares) {
172	      try {
173	        result = await postMw({
174	          toolName,
175	          args: initialArgs,
176	          result,
177	          workspace: this.workspace,
178	        });
179	      } catch {
180	        // If post-middleware fails, keep existing result
181	      }
