#!/usr/bin/env python3
"""Deterministic accuracy suite: HumanEval, long-context needle, tool calls, code-edit fidelity.
Usage: evalx.py <label> <base_url> <keyfile|-> <model> [suite,...]
Greedy decoding (temperature 0). Generated code runs as `nobody` in a net-less namespace."""
import json, os, re, subprocess, sys, tempfile, time, urllib.request, urllib.error, concurrent.futures as cf, random

label, base, keyfile, model = sys.argv[1:5]
suites = (sys.argv[5] if len(sys.argv) > 5 else "humaneval,needle,tools,edit").split(",")
key = subprocess.run(["sudo", "cat", keyfile], capture_output=True, text=True).stdout.strip() if keyfile != "-" else ""
H = {"Content-Type": "application/json"}
if key: H["Authorization"] = "Bearer " + key


def chat(messages, max_tokens=1024, tools=None, timeout=900):
    body = {"model": model, "messages": messages, "max_tokens": max_tokens, "temperature": 0}
    if tools: body.update(tools=tools, tool_choice="auto")
    for attempt in range(3):
        try:
            req = urllib.request.Request(base + "/v1/chat/completions", json.dumps(body).encode(), H)
            return json.load(urllib.request.urlopen(req, timeout=timeout))
        except urllib.error.HTTPError as e:
            return {"error": e.read().decode()[:200]}
        except Exception as e:
            err = repr(e)
            time.sleep(2)
    return {"error": err}


def content(r):
    try: return r["choices"][0]["message"].get("content") or ""
    except Exception: return ""


def run_py(code, timeout=15):
    d = tempfile.mkdtemp(prefix="ev_", dir="/tmp"); os.chmod(d, 0o777)
    p = os.path.join(d, "t.py"); open(p, "w").write(code); os.chmod(p, 0o644)
    try:
        r = subprocess.run(["sudo", "-n", "unshare", "--net", "--", "runuser", "-u", "nobody", "--", "timeout", str(timeout), "python3", p],
                           capture_output=True, text=True, cwd=d, timeout=timeout + 10)
        return r.returncode == 0, (r.stderr or r.stdout)[-300:]
    except Exception as e:
        return False, repr(e)
    finally:
        subprocess.run(["rm", "-rf", d])


def code_block(text, entry=None):
    blocks = re.findall(r"```(?:python|py)?\s*\n(.*?)```", text, re.S)
    if entry:
        for b in blocks:
            if re.search(r"def\s+" + re.escape(entry) + r"\s*\(", b): return b
    return blocks[0] if blocks else text


results = {}

# ---------------------------------------------------------------- HumanEval
if "humaneval" in suites:
    probs = [json.loads(l) for l in open("/tmp/evalx/he.jsonl")]
    def one(p):
        header = "\n".join(l for l in p["prompt"].splitlines() if l.startswith(("import ", "from ")))
        r = chat([{"role": "system", "content": "You are an expert Python programmer."},
                  {"role": "user", "content": "Complete the following Python function. Return the complete, final function (with any imports it needs) in a single ```python code block and nothing else.\n\n" + p["prompt"]}], max_tokens=1024)
        text = content(r); sol = code_block(text, p["entry_point"])
        prog = header + "\n" + p["prompt"].split("def ")[0] * 0 + sol + "\n\n" + p["test"] + f"\n\ncheck({p['entry_point']})\n"
        ok, err = run_py(prog)
        return p["task_id"], ok, err, text[:0]
    t = time.time(); res = []
    with cf.ThreadPoolExecutor(2) as ex: res = list(ex.map(one, probs))
    passed = sum(1 for _, ok, _, _ in res if ok)
    results["humaneval"] = {"pass@1": round(100 * passed / len(res), 1), "passed": passed, "n": len(res), "failed": [i for i, ok, _, _ in res if not ok], "secs": round(time.time() - t)}
    print(label, "HumanEval", results["humaneval"], flush=True)

# ---------------------------------------------------------------- needle in a haystack
if "needle" in suites:
    random.seed(7)
    def haystack(tokens, depth, secret, kind):
        lines = []; n = 0; target = int(tokens * 3.3)
        while n < target:
            i = random.randint(1000, 9999)
            l = f"[{i}] audit record: service=gw-{random.randint(1,40)} status={random.choice(['ok','ok','retry','ok'])} latency_ms={random.randint(5,900)} ref={random.randint(100000,999999)}"
            lines.append(l); n += len(l) + 1
        pos = int(len(lines) * depth)
        lines.insert(pos, f"NOTE: the vault-{kind} access code is {secret}. Remember it.")
        return "\n".join(lines)
    cases = []
    for tokens in (4000, 16000, 48000):
        for depth in (0.1, 0.5, 0.9):
            secret = f"{random.choice(['AX','QZ','MN','TR'])}-{random.randint(10000,99999)}-{random.choice(['k','m','p'])}"
            cases.append((tokens, depth, secret))
    def one(c):
        tokens, depth, secret = c
        text = haystack(tokens, depth, secret, "alpha")
        r = chat([{"role": "user", "content": text + "\n\nQuestion: what is the vault-alpha access code? Answer with the code only."}], max_tokens=30)
        return tokens, depth, secret in content(r)
    t = time.time(); res = [one(c) for c in cases]
    by = {}
    for tk, d, ok in res: by.setdefault(tk, []).append(ok)
    results["needle"] = {str(k): f"{sum(v)}/{len(v)}" for k, v in by.items()}; results["needle"]["total"] = f"{sum(ok for *_, ok in res)}/{len(res)}"; results["needle"]["secs"] = round(time.time() - t)
    print(label, "Needle", results["needle"], flush=True)

# ---------------------------------------------------------------- tool calls
if "tools" in suites:
    T = lambda name, desc, props, req: {"type": "function", "function": {"name": name, "description": desc, "parameters": {"type": "object", "properties": props, "required": req}}}
    tools = [
        T("read_file", "Read a file", {"path": {"type": "string"}, "start_line": {"type": "number"}, "end_line": {"type": "number"}}, ["path"]),
        T("write_file", "Write a file", {"path": {"type": "string"}, "content": {"type": "string"}, "overwrite": {"type": "boolean"}}, ["path", "content"]),
        T("run_command", "Run a shell command", {"command": {"type": "string"}, "cwd": {"type": "string"}, "timeout_secs": {"type": "number"}}, ["command"]),
        T("search_code", "Search code", {"query": {"type": "string"}, "is_regex": {"type": "boolean"}, "max_results": {"type": "number"}, "file_pattern": {"type": "string"}}, ["query"]),
        T("edit_file", "Replace text in a file", {"path": {"type": "string"}, "old_content": {"type": "string"}, "new_content": {"type": "string"}}, ["path", "old_content", "new_content"]),
        T("git_log", "Show commit history", {"max_commits": {"type": "number"}}, []),
        T("fetch_web", "Fetch a URL", {"url": {"type": "string"}, "max_length": {"type": "number"}}, ["url"]),
        T("spawn_subagent", "Delegate a task", {"prompt": {"type": "string"}, "max_steps": {"type": "number"}}, ["prompt"]),
    ]
    C = [
        ("Read src/lib.rs from line 5 to line 40", "read_file", {"path": "src/lib.rs", "start_line": 5, "end_line": 40}),
        ("Show me the file config/app.yaml", "read_file", {"path": "config/app.yaml"}),
        ("Create notes/todo.md containing exactly: buy milk. Overwrite if it exists.", "write_file", {"path": "notes/todo.md", "content": "buy milk", "overwrite": True}),
        ("Run `npm test -- --silent` in the web directory with a 300 second timeout", "run_command", {"command": "npm test -- --silent", "cwd": "web", "timeout_secs": 300}),
        ("Run cargo clippy", "run_command", {"command": "cargo clippy"}),
        ("Find all occurrences of the regex ^fn main in rust files, at most 20 results (file pattern \\.rs$)", "search_code", {"query": "^fn main", "is_regex": True, "max_results": 20, "file_pattern": "\\.rs$"}),
        ("Search the code for the plain text TODO", "search_code", {"query": "TODO"}),
        ("In app.py replace 'DEBUG = True' with 'DEBUG = False'", "edit_file", {"path": "app.py", "old_content": "DEBUG = True", "new_content": "DEBUG = False"}),
        ("Show the last 5 commits", "git_log", {"max_commits": 5}),
        ("Fetch https://example.com/docs/api and return at most 2000 characters", "fetch_web", {"url": "https://example.com/docs/api", "max_length": 2000}),
        ("Delegate this to a subagent with at most 6 steps: summarize the auth module", "spawn_subagent", {"prompt": "summarize the auth module", "max_steps": 6}),
        ("Read the file Cargo.toml", "read_file", {"path": "Cargo.toml"}),
        ("List the files in the current directory using the shell", "run_command", {"command": "ls"}),
        ("Write the text hello world to out/hello.txt", "write_file", {"path": "out/hello.txt", "content": "hello world"}),
        ("Show the last 20 commits", "git_log", {"max_commits": 20}),
        ("In lib/util.js change 'var x = 1;' to 'let x = 1;'", "edit_file", {"path": "lib/util.js", "old_content": "var x = 1;", "new_content": "let x = 1;"}),
        ("Look up the plain text 'fn parse' limited to 5 results", "search_code", {"query": "fn parse", "max_results": 5}),
        ("Fetch the page https://docs.rs/serde", "fetch_web", {"url": "https://docs.rs/serde"}),
        ("Read lines 100 to 120 of tests/it.py", "read_file", {"path": "tests/it.py", "start_line": 100, "end_line": 120}),
        ("Run `make build` in the directory build", "run_command", {"command": "make build", "cwd": "build"}),
    ]
    def one(c):
        prompt, fn, exp = c
        r = chat([{"role": "system", "content": "You are a coding agent. Call exactly one tool that accomplishes the request."}, {"role": "user", "content": prompt}], max_tokens=300, tools=tools)
        try:
            tc = r["choices"][0]["message"].get("tool_calls") or []
            call = tc[0]["function"]; args = json.loads(call["arguments"])
        except Exception:
            return False, False
        name_ok = call["name"] == fn
        norm = lambda v: v.strip() if isinstance(v, str) else v
        args_ok = name_ok and all(k in args and norm(args[k]) == norm(v) for k, v in exp.items())
        return name_ok, args_ok
    res = [one(c) for c in C]
    results["tools"] = {"right_function": f"{sum(a for a, _ in res)}/{len(res)}", "exact_args": f"{sum(b for _, b in res)}/{len(res)}"}
    print(label, "Tools", results["tools"], flush=True)

# ---------------------------------------------------------------- code-edit fidelity
if "edit" in suites:
    base_mod = '''import json

class Inventory:
    def __init__(self):
        self.items = {}

    def add(self, name, qty):
        if qty <= 0:
            raise ValueError("qty must be positive")
        self.items[name] = self.items.get(name, 0) + qty

    def remove(self, name, qty):
        have = self.items.get(name, 0)
        if qty > have:
            raise ValueError("insufficient stock")
        self.items[name] = have - qty
        if self.items[name] == 0:
            del self.items[name]

    def total(self):
        return sum(self.items.values())

    def names(self):
        return sorted(self.items)

    def dump(self):
        return json.dumps(self.items, sort_keys=True)


def restock(inv, names, qty):
    for n in names:
        inv.add(n, qty)
    return inv.total()


def report(inv):
    return "\\n".join(f"{n}: {inv.items[n]}" for n in inv.names())
'''
