class WorkerRecord:
    worker_id: str
    public_model_id: str
    model_id: str
    revision: str
    artifact_digest: str
    runtime_image_digest: str
    topology: str
    gpu_assignment: tuple[str, ...]
    capabilities: frozenset[str]
    context_limit: int
    max_output_tokens: int
    max_concurrency: int
    resource_envelope: dict[str, Any]
    evidence_ids: tuple[str, ...]
    registry_version: int
    measured_at: str
    valid_until: str
    status: str = "measured"
    healthy: bool = True
    endpoint: str | None = None
    auth_token: str | None = None

    def __post_init__(self) -> None:
        if self.revision in {"", "main", "latest"}:
            raise ValueError("worker revision must be exact")
        if not self.evidence_ids:
            raise ValueError("worker capability records require evidence")

    @property
    def identity_hash(self) -> str:
        return _hash({
            "worker_id": self.worker_id,
            "public_model_id": self.public_model_id,
