    fn update_engine_rates(&mut self, snap: &orchestrator::Snapshot) {
        let present: std::collections::BTreeSet<&String> = snap
            .health
            .workers
            .iter()
            .filter(|(_, w)| w.engine_stats.is_some())
            .map(|(name, _)| name)
            .collect();
        self.orch_worker_rates.retain(|name, _| present.contains(name));
