    def __init__(self, value, children=None):
        self.value = value
        self.children = children or []


def flatten(node):
    out = []
    stack = [node]
    while stack:
        n = stack.pop()
        out.append(n.value)
        stack.extend(reversed(n.children))
    return out


def depth(node):
    best = 0
    stack = [(node, 1)]
    while stack:
        n, d = stack.pop()
        best = max(best, d)
        for c in n.children:
