    pub fn new(settings: &Settings, defs: Vec<InstanceDef>) -> Result<App> {
        let mut runtimes = Vec::with_capacity(defs.len());
        for def in defs {
            let src = source::build(def.kind, &def.url, def.api_key.as_deref())?;
            // Best-effort, one-time metadata — never re-fetched, never
            // required. Only meaningful for a Direct-kind vLLM endpoint;
            // a Prometheus server doesn't expose /version or /v1/models
            // itself.
            let (vllm_version, max_model_len) = match def.kind {
                crate::config::SourceKind::Direct => {
                    source::probe_direct_info(&def.url, def.api_key.as_deref())
                }
                crate::config::SourceKind::Prometheus => (None, None),
            };
            // Sender is created per poll round; the placeholder receiver just
            // sits empty until the first fetch starts.
            let (_tx, rx) = mpsc::channel::<FetchResult>();
            runtimes.push(Runtime {
                source: src,
                def,
                rx,
                    },
                };
                let metrics_color = match health {
                    Health::Ok => GOOD,
                    Health::Stale | Health::Down => WARN,
                };
                lines.push(stat_line("metrics", &truncate(&metrics_desc, value_budget), metrics_color));

                if matches!(rt.def.kind, crate::config::SourceKind::Direct) {
                    lines.push(stat_line("vllm", rt.vllm_version.as_deref().unwrap_or("unknown"), DIM));
                }

                if let Some(s) = &rt.snapshot {
                    let model = s.model.clone().unwrap_or_else(|| "-".into());
                    let ctx = rt
                        .max_model_len
                        .map(|n| format!("  ({} ctx)", util::fmt_si(n as f64)))
                        .unwrap_or_default();
                    lines.push(stat_line("model", &truncate(&format!("{model}{ctx}"), value_budget), DIM));
                }
            }
            // place that *does* need to refuse an ambiguous pick (runtime
            // reconnection, in app.rs).
            for inst in discovered {
                defs.push(InstanceDef {
                    name: String::new(),
                    kind: SourceKind::Direct,
                    url: inst.url,
                    api_key: configured_api_key.clone(),
                    discovered_via: Some(inst.discovered_via),
                    auth: Some(inst.auth),
                    confidence: Some(inst.confidence),
                });
            }
        }
    } else {
        // A --url/TOML instance that explicitly points at the local
        // loopback but didn't set its own key still gets the configured
        // one — the common case of `-u http://localhost:8000` plus
        // VLLM_API_KEY in vllm-top's own environment. Non-loopback file
        // instances are left alone: we don't assume a remote server wants
        // the local key.
        if let Some(key) = &configured_api_key {
            for def in defs.iter_mut() {
                if def.api_key.is_none() && is_loopback_url(&def.url) {
                    def.api_key = REDACTED;
                }
            }
        }
    }

    let mut seen = HashSet::new();
    for (idx, def) in defs.iter_mut().enumerate() {
        if def.name.is_empty() {
            def.name = default_name(&def.url, idx);
        }
        let mut candidate = def.name.clone();
        let mut n = 2;
        while !seen.insert(candidate.clone()) {
            candidate = format!("{}#{}", def.name, n);
            n += 1;
        }
        def.name = candidate;
    }

    let poll_ms = cli.poll_ms.or(file.poll_ms).unwrap_or(1_000).max(200);
    let history = cli.history.or(file.history).unwrap_or(240).max(16);
