#!/usr/bin/env python3
"""Reviewer benchmark: can a model tell a correct HumanEval solution from a mutated, test-failing one?
  reviewx.py build                      -> builds /tmp/evalx/review_set.json (verified mutants)
  reviewx.py run <label> <url> <keyfile|-> <model> [think|nothink] [limit]
Balanced set (equal correct / buggy). Greedy decoding. Scores accuracy, bug recall, false-positive rate."""
import ast, copy, json, os, random, re, subprocess, sys, tempfile, time, urllib.request, concurrent.futures as cf

SET = "/tmp/evalx/review_set.json"


def run_py(code, timeout=15):
    d = tempfile.mkdtemp(prefix="rv_", dir="/tmp"); p = os.path.join(d, "t.py"); open(p, "w").write(code)
    mounts = (["--symlink", "usr/bin", "/bin", "--symlink", "usr/lib", "/lib", "--symlink", "usr/lib64", "/lib64"]
              if os.path.islink("/bin") else ["--ro-bind", "/bin", "/bin", "--ro-bind", "/lib", "/lib", "--ro-bind", "/lib64", "/lib64"])
    cmd = ["bwrap", "--ro-bind", "/usr", "/usr", "--ro-bind", "/etc/alternatives", "/etc/alternatives", *mounts, "--proc", "/proc",
           "--dev", "/dev", "--tmpfs", "/tmp", "--bind", d, d, "--chdir", d, "--unshare-all", "--die-with-parent", "--clearenv",
           "--setenv", "PATH", "/usr/bin:/bin", "timeout", str(timeout), "python3", p]
    try:
        return subprocess.run(cmd, capture_output=True, text=True, timeout=timeout + 10).returncode == 0
    except Exception:
        return False
    finally:
        subprocess.run(["rm", "-rf", d])


SWAP_CMP = {ast.Lt: ast.LtE, ast.LtE: ast.Lt, ast.Gt: ast.GtE, ast.GtE: ast.Gt, ast.Eq: ast.NotEq, ast.NotEq: ast.Eq}
SWAP_BIN = {ast.Add: ast.Sub, ast.Sub: ast.Add, ast.Mult: ast.FloorDiv, ast.FloorDiv: ast.Mult, ast.Mod: ast.FloorDiv}


class Mutator(ast.NodeTransformer):
    def __init__(self, target): self.target, self.i, self.done = target, -1, False
    def _hit(self):
        self.i += 1
        if self.i == self.target and not self.done:
            self.done = True; return True
        return False
    def visit_Compare(self, n):
        self.generic_visit(n)
        if len(n.ops) == 1 and type(n.ops[0]) in SWAP_CMP and self._hit(): n.ops = [SWAP_CMP[type(n.ops[0])]()]
        return n
    def visit_BinOp(self, n):
        self.generic_visit(n)
        if type(n.op) in SWAP_BIN and self._hit(): n.op = SWAP_BIN[type(n.op)]()
        return n
    def visit_BoolOp(self, n):
        self.generic_visit(n)
        if self._hit(): n.op = ast.Or() if isinstance(n.op, ast.And) else ast.And()
        return n
    def visit_UnaryOp(self, n):
        self.generic_visit(n)
        if isinstance(n.op, ast.Not) and self._hit(): return n.operand
        return n
    def visit_Constant(self, n):
        if isinstance(n.value, int) and not isinstance(n.value, bool) and self._hit(): return ast.copy_location(ast.Constant(n.value + 1), n)
        return n


def mutants(src):
    out = []
    for t in range(40):
        tree = ast.parse(src); m = Mutator(t); new = m.visit(tree)
        if not m.done: break
        try: out.append(ast.unparse(ast.fix_missing_locations(new)))
        except Exception: pass
    return out


def build():
    probs = [json.loads(l) for l in open("/tmp/evalx/he.jsonl")]
    random.seed(11); items = []
    def work(p):
        full = p["prompt"] + p["canonical_solution"]
        try: norm = ast.unparse(ast.parse(full))
        except Exception: return None
        test = lambda code: run_py(code + "\n\n" + p["test"] + f"\n\ncheck({p['entry_point']})\n")
        if not test(norm): return None
        cands = [m for m in mutants(full) if m != norm]; random.Random(p["task_id"]).shuffle(cands)
        for m in cands[:10]:
            if not test(m): return {"task_id": p["task_id"], "spec": p["prompt"], "correct": norm, "buggy": m}
        return {"task_id": p["task_id"], "spec": p["prompt"], "correct": norm, "buggy": None}
    with cf.ThreadPoolExecutor(4) as ex: res = [r for r in ex.map(work, probs) if r]
    json.dump(res, open(SET, "w")); print("problems with verified correct solution:", len(res), "| with verified buggy mutant:", sum(1 for r in res if r["buggy"]))


def run(label, base, keyfile, model, mode="nothink", limit=0):
    key = subprocess.run(["sudo", "cat", keyfile], capture_output=True, text=True).stdout.strip() if keyfile != "-" else ""
    H = {"Content-Type": "application/json"}; H.update({"Authorization": "Bearer " + key} if key else {})
