    for l in get("/metrics").splitlines():
        if l and not l.startswith("#"):
            k,v=l.split(); d[k.replace("llamacpp:","")]=float(v)
    return d
def post():
    b={"model":"x","messages":[{"role":"user","content":"Write a detailed 400 word essay on the history of the bicycle."}],"max_tokens":350,"temperature":0.2,"chat_template_kwargs":{"enable_thinking":False}}
    urllib.request.urlopen(urllib.request.Request("http://127.0.0.1:8000/v1/chat/completions",json.dumps(b).encode(),H),timeout=120).read()
base=metrics(); t=threading.Thread(target=post); t.start(); t0=time.time()
rows=[]
while t.is_alive() and time.time()-t0<60:
    s=json.loads(get("/slots"))[0]; m=metrics()
    nt=s.get("next_token",[{}])[0] if isinstance(s.get("next_token"),list) else s.get("next_token",{})
    rows.append((round(time.time()-t0,1),s["is_processing"],s.get("n_prompt_tokens"),nt.get("n_decoded"),nt.get("n_remain"),m["requests_processing"],m["predicted_tokens_seconds"],m["prompt_tokens_seconds"],m["n_tokens_max"]))
    time.sleep(0.7)
t.join(); end=metrics()
print("t, is_processing, n_prompt_tokens, n_decoded, n_remain, req_processing, predicted_tok/s(avg), prompt_tok/s(avg), n_tokens_max")
for r in rows[::2][:10]: print(r)
for k in ("prompt_tokens_total","prompt_tokens_cached_total","tokens_predicted_total","prompt_seconds_total","tokens_predicted_seconds_total","n_decode_total"): print(f"delta {k}: {end[k]-base[k]:.2f}")
s=json.loads(get("/slots"))[0]; print("slot keys:",[k for k in s if k not in ("params",)])
print("next_token:",json.dumps(s.get("next_token"))[:200])
EOF
