fn merge_hist<'a>(iter: impl Iterator<Item = &'a Histogram>) -> Histogram {
    let mut out = Histogram::default();
    let mut weight = 0.0_f64;
    for h in iter {
        out.count += h.count;
        out.sum += h.sum;
        if h.count > 0.0 {
            out.p50 += h.p50 * h.count;
            out.p99 += h.p99 * h.count;
            weight += h.count;
        }
