        let mut snap = sample_orchestrator_snapshot();
        let w = snap.health.workers.get_mut("b0-live-tp1-worker1").expect("worker");
        w.pool = Some("lead".into());
        w.engine = Some("llama.cpp".into());
        w.engine_stats = Some(EngineStats {
