        lbl=[open(f"{h}/energy{i}_label").read().strip() for i in (1,2)]
        card=int(open(h+"/energy1_input").read()) if lbl[0]=="card" else int(open(h+"/energy2_input").read())
        out[bdf]=card/1e6
    return out
order=sorted(snap())
def gen(model):
    b={"model":model,"messages":[{"role":"user","content":"Write a detailed 500 word essay on the history of the railway."}],"max_tokens":600,"temperature":0.2,"chat_template_kwargs":{"enable_thinking":False}}
